/** P2 大小写敏感的 opaque runtime ID；值本身不携带任何 authority。 */
public final class RuntimeResolutionOwnerId implements Comparable<RuntimeResolutionOwnerId>{private final String value;private RuntimeResolutionOwnerId(String value){this.value=requireValue(value);}public static RuntimeResolutionOwnerId of(String value){return new RuntimeResolutionOwnerId(value);}public String value(){return value;}@Override public int compareTo(RuntimeResolutionOwnerId other){return value.compareTo(Objects.requireNonNull(other,"other").value);}@Override public boolean equals(Object other){return this==other||other instanceof RuntimeResolutionOwnerId&&value.equals(((RuntimeResolutionOwnerId)other).value);}@Override public int hashCode(){return value.hashCode();}@Override public String toString(){return value;}private static String requireValue(String raw){Objects.requireNonNull(raw,"value");if(raw.trim().isEmpty()||!raw.equals(raw.trim()))throw new IllegalArgumentException("value must be non-blank and trimmed");return raw;}}
